from pathlib import Path
import re, sys

path = Path(sys.argv[1] if len(sys.argv) > 1 else 'bgaplays.html')
text = path.read_text(encoding='utf-8')

if 'bgaplays-credits-v1' in text:
    print('BGA Plays credits patch already applied')
    raise SystemExit(0)


def exact(old, new, label):
    global text
    if old not in text:
        raise SystemExit(f'Missing anchor: {label}')
    text = text.replace(old, new, 1)


def regex(pattern, repl, label, flags=re.S):
    global text
    text2, count = re.subn(pattern, repl, text, count=1, flags=flags)
    if count != 1:
        raise SystemExit(f'Expected one match for {label}, got {count}')
    text = text2

