# Credit helper functions before bggMetaFor
credit_helpers = r'''
function decodeHtml(s){const t=document.createElement('textarea');t.innerHTML=String(s||'');return t.value}
function cleanCreditName(s){return decodeHtml(String(s||'')).replace(/\s+/g,' ').trim()}
function creditObj(name,id=''){name=cleanCreditName(name);return name?{name,id:String(id||'')}:null}
function uniqCredits(items){const m=new Map();for(const item of items||[]){const c=typeof item==='string'?creditObj(item):creditObj(item?.name,item?.id);if(!c)continue;const k=normName(c.name);if(!m.has(k)||(!m.get(k).id&&c.id))m.set(k,c)}return[...m.values()].sort((a,b)=>a.name.localeCompare(b.name))}
function studioSplit(value,role){const s=cleanCreditName(value);if(!s)return[];if(role==='publishers')return[creditObj(s)].filter(Boolean);return uniqCredits(s.split(/\s*,\s*/).filter(Boolean))}
function creditDataFor(rowOrGame){const game=typeof rowOrGame==='string'?rowOrGame:rowOrGame.game,key=normName(game),seed=state.studioCredits.get(key)||{},rich=state.creditsMap.get(key)||{};return{bggId:rich.bggId||'',bggName:rich.bggName||'',thumb:rich.thumb||'',publishers:uniqCredits([...(seed.publishers||[]),...(rich.publishers||[])]),designers:uniqCredits([...(seed.designers||[]),...(rich.designers||[])]),artists:uniqCredits([...(seed.artists||[]),...(rich.artists||[])])}}
function creditNames(rowOrGame,role){return creditDataFor(rowOrGame)[role]||[]}
function creditMatches(rowOrGame,role,q){if(!q)return true;q=q.toLowerCase();return creditNames(rowOrGame,role).some(c=>c.name.toLowerCase().includes(q))}
function allKnownCredits(role){const m=new Map();for(const rows of state.historyMap.values()){const game=rows[0]?.game;if(!game)continue;for(const c of creditNames(game,role))m.set(normName(c.name),c.name)}return[...m.values()].sort((a,b)=>a.localeCompare(b))}
function populateCreditFilterLists(){for(const [role,list] of [['publishers',els.publisherList],['designers',els.designerList],['artists',els.artistList]])list.innerHTML=allKnownCredits(role).map(n=>`<option value="${esc(n)}"></option>`).join('');refreshCreditsInfo()}
function aliasSearchName(game){const key=normName(game);for(const line of String(settings().bggAliases||'').split(/\r?\n/)){const i=line.indexOf('=');if(i<0)continue;if(normName(line.slice(0,i))===key)return line.slice(i+1).trim()}return game}
function creditChipHtml(c,role){const label=role==='publishers'?'Publisher':role==='designers'?'Designer':'Artist';return`<button class="credit-chip" data-credit-role="${role}" data-credit="${esc(c.name)}" title="Filter by ${label}: ${esc(c.name)}">${esc(c.name)}</button>`}
function historyCreditsHtml(row){const d=creditDataFor(row),groups=[['publishers','Publishers'],['designers','Designers'],['artists','Artists']];return groups.map(([role,label])=>`<section class="credit-group"><h4>${label}</h4><div class="credit-chips">${d[role].length?d[role].map(c=>creditChipHtml(c,role)).join(''):'<span class="credit-empty">Not loaded</span>'}</div></section>`).join('')}
function applyCreditFilter(role,name){const el=role==='publishers'?els.publisherFilter:role==='designers'?els.designerFilter:els.artistFilter;el.value=name;state.advancedOpen=true;els.advancedFilters.classList.add('open');$('advancedBtn').textContent='Less';if(els.historyDialog.open)els.historyDialog.close();setView('games');applyFilters()}
async function loadStudioCredits(){try{const res=await fetch('./bga-studio.csv',{cache:'default'});if(!res.ok)throw new Error(`HTTP ${res.status}`);const rows=parseCsv(await res.text());if(rows.length<2)return;const head=rows[0],idx=Object.fromEntries(head.map((h,i)=>[String(h).trim(),i]));const map=new Map();for(const r of rows.slice(1)){const game=cleanCreditName(r[idx['Game name']]);if(!game)continue;map.set(normName(game),{publishers:studioSplit(r[idx['Publisher']],'publishers'),designers:studioSplit(r[idx['Designer']],'designers'),artists:[]})}state.studioCredits=map;populateCreditFilterLists();if(state.rows.length)applyFilters();console.log(LOG,`Loaded BGA Studio credits for ${map.size} games`)}catch(err){console.warn(LOG,'BGA Studio credits unavailable',err);refreshCreditsInfo()}}
async function loadCreditCache(){try{const cached=await dbGet('credits-v1');if(cached?.entries){state.creditsMap=new Map(cached.entries);state.creditsLoadedAt=cached.loadedAt||null;for(const [key,d] of state.creditsMap){if(d.thumb)state.thumbs.set(key,d.thumb);if(d.bggId)state.bggMeta.set(key,{id:d.bggId,name:d.bggName||'',thumb:d.thumb||''})}populateCreditFilterLists()}}catch(err){console.warn(LOG,'credits cache',err)}}
async function saveCreditCache(){state.creditsLoadedAt=Date.now();await dbSet('credits-v1',{entries:[...state.creditsMap.entries()],loadedAt:state.creditsLoadedAt})}
async function helperXml(query){const urls=[`/api/bgg-helper?${query}`];if(location.hostname!=='board-game-lab.vercel.app')urls.push(`https://board-game-lab.vercel.app/api/bgg-helper?${query}`);let last=null;for(const url of urls){try{const res=await fetch(url,{cache:'no-store'}),txt=await res.text();if(!res.ok)throw new Error(`HTTP ${res.status}`);if(!/^\s*</.test(txt))throw new Error('Not XML');return txt}catch(err){last=err}}throw last||new Error('BGG helper unavailable')}
async function resolveBggId(game){const key=normName(game),known=state.creditsMap.get(key);if(known?.bggId)return known.bggId;const alias=aliasKey(key),collection=state.bggMeta.get(alias)||state.bggMeta.get(key);if(collection?.id)return collection.id;const q=aliasSearchName(game),xmlText=await helperXml(`endpoint=search&type=boardgame&exact=1&query=${encodeURIComponent(q)}`),xml=new DOMParser().parseFromString(xmlText,'text/xml');const items=[...xml.querySelectorAll('item')];if(!items.length)return'';const exactItem=items.find(i=>normName(i.querySelector('name')?.getAttribute('value')||'')===normName(q))||items[0];return exactItem.getAttribute('id')||''}
function parseThingCredits(xmlText){const xml=new DOMParser().parseFromString(xmlText,'text/xml'),item=xml.querySelector('item[type="boardgame"], item');if(!item)throw new Error('BGG Thing returned no game');const links=type=>[...item.querySelectorAll(`link[type="${type}"]`)].map(l=>creditObj(l.getAttribute('value'),l.getAttribute('id'))).filter(Boolean);return{bggId:item.getAttribute('id')||'',bggName:item.querySelector('name[type="primary"]')?.getAttribute('value')||item.querySelector('name')?.getAttribute('value')||'',thumb:item.querySelector('thumbnail')?.textContent?.trim()||'',publishers:uniqCredits(links('boardgamepublisher')),designers:uniqCredits(links('boardgamedesigner')),artists:uniqCredits(links('boardgameartist')),loadedAt:Date.now(),source:'BGG Thing'}}
async function enrichOneCreditGame(game,force=false){const key=normName(game),old=state.creditsMap.get(key);if(!force&&old?.loadedAt&&Date.now()-old.loadedAt<30*24*60*60*1000)return false;const id=await resolveBggId(game);if(!id){state.creditsMap.set(key,{...(old||{}),miss:true,loadedAt:Date.now()});return false}const xml=await helperXml(`endpoint=thing&id=${encodeURIComponent(id)}`),d=parseThingCredits(xml);state.creditsMap.set(key,d);if(d.thumb)state.thumbs.set(key,d.thumb);state.bggMeta.set(key,{id:d.bggId,name:d.bggName,thumb:d.thumb});return true}
function uniqueFilteredGames(){const m=new Map();for(const r of state.filtered)m.set(r.nameKey,r.game);return[...m.values()]}
function rankedGames(limit=50){const m=new Map();for(const r of state.filtered.length?state.filtered:state.rows)m.set(r.game,(m.get(r.game)||0)+r.totalPlayed);return[...m].sort((a,b)=>b[1]-a[1]).slice(0,limit).map(x=>x[0])}
async function enrichCredits(games,force=false){if(state.creditsLoading)return;const uniq=[...new Set(games)].filter(Boolean);if(!uniq.length)return;state.creditsLoading=true;state.creditsDone=0;state.creditsTarget=uniq.length;refreshCreditsInfo();let cursor=0,changed=0;async function worker(){while(cursor<uniq.length){const game=uniq[cursor++];try{if(await enrichOneCreditGame(game,force))changed++}catch(err){console.warn(LOG,'credit enrich',game,err)}state.creditsDone++;refreshCreditsInfo();await new Promise(r=>setTimeout(r,120))}}try{await Promise.all(Array.from({length:Math.min(3,uniq.length)},worker));await saveCreditCache();populateCreditFilterLists();applyFilters();render();console.log(LOG,`Credits enriched: ${changed}/${uniq.length}`)}finally{state.creditsLoading=false;refreshCreditsInfo()}}
function refreshCreditsInfo(){if(!els.creditsInfo)return;const games=[...state.historyMap.values()].map(r=>r[0]?.game).filter(Boolean),covered=games.filter(g=>{const d=creditDataFor(g);return d.publishers.length||d.designers.length||d.artists.length}).length,rich=state.creditsMap.size,pubs=allKnownCredits('publishers').length,designers=allKnownCredits('designers').length,artists=allKnownCredits('artists').length,p=state.creditsTarget?Math.round(state.creditsDone/state.creditsTarget*100):0;els.creditsInfo.innerHTML=`<strong>${full(covered)}</strong> / ${full(games.length)} BGA games have known credits<br><strong>${full(pubs)}</strong> publishers • <strong>${full(designers)}</strong> designers • <strong>${full(artists)}</strong> artists<br>BGA Studio seed: <strong>${full(state.studioCredits.size)}</strong> games<br>BGG enriched/cache: <strong>${full(rich)}</strong> games${state.creditsLoadedAt?` • ${timeAgo(state.creditsLoadedAt)}`:''}${state.creditsLoading?`<br><strong>Enriching ${full(state.creditsDone)} / ${full(state.creditsTarget)}</strong><div class="credits-progress" style="--p:${p}%"><i></i></div>`:'<div class="status-line"><span class="status-pill good">Cached locally in IndexedDB</span></div>'}`}
function buildCreditsRows(){const role=els.creditsRole.value,minGames=Math.max(1,Number(els.creditsMinGames.value)||1),map=new Map();for(const r of state.filtered){for(const c of creditNames(r,role)){const k=normName(c.name);let x=map.get(k);if(!x){x={credit:c.name,creditId:c.id||'',role,gamesSet:new Set(),records:0,totalPlayed:0,realtime:0,turnbased:0,timeSpent:0,sumAudience:0,peakAudience:0};map.set(k,x)}x.gamesSet.add(r.game);x.records++;x.totalPlayed+=r.totalPlayed;x.realtime+=r.realtime;x.turnbased+=r.turnbased;x.timeSpent+=r.timeSpent;x.sumAudience+=r.audience;x.peakAudience=Math.max(x.peakAudience,r.audience)}}state.viewRows=[...map.values()].map(x=>({...x,games:x.gamesSet.size,avgAudience:x.records?x.sumAudience/x.records:0})).filter(x=>x.games>=minGames);sortViewRows()}
'''
exact('function bggMetaFor(row){', credit_helpers + '\nfunction bggMetaFor(row){', 'credit helpers')

