regex(r"function render\(\)\{.*?\nfunction renderMatrix", r'''function render(){els.resultsPanel.classList.toggle('matrix-mode',state.view==='matrix');els.resultsPanel.classList.toggle('credits-mode',state.view==='credits');els.matrixSummary.hidden=state.view!=='matrix';if(state.view==='matrix'){renderMatrix();renderChart();return}els.resultsTable.className='';const total=state.viewRows.length,pages=Math.max(1,Math.ceil(total/state.pageSize));if(state.page>pages)state.page=pages;const start=(state.page-1)*state.pageSize,pageRows=state.viewRows.slice(start,start+state.pageSize),cols=columnsForView(),title=state.view==='records'?'Records':state.view==='games'?'Games summary':state.view==='months'?'Months summary':`${els.creditsRole.options[els.creditsRole.selectedIndex].text} ranking`;els.resultTitle.textContent=`${title} • ${full(total)}`;els.tableHead.innerHTML=`<tr>${cols.map(([key,label])=>`<th data-key="${key}" class="${key==='game'?'game-cell':key==='credit'?'credit-cell':key==='period'?'':'num'}">${label}${state.sortKey===key?(state.sortDir==='asc'?' ↑':' ↓'):''}</th>`).join('')}</tr>`;els.tableBody.innerHTML=pageRows.length?pageRows.map(r=>`<tr>${cols.map(([key])=>key==='game'?`<td class="game-cell">${gameIdentityHtml(r,{spark:state.view==='games'})}</td>`:key==='credit'?`<td class="credit-cell"><button class="credit-link" data-credit-role="${r.role}" data-credit="${esc(r.credit)}">${esc(r.credit)}</button></td>`:`<td class="${key==='period'?'':'num'} ${['audience','latestAudience','avgAudience','peakAudience'].includes(key)?'share':''} ${['premium','latestPremium'].includes(key)?'premium':''}">${key==='latestDelta'?cellValue(r,key):esc(cellValue(r,key))}</td>`).join('')}</tr>`).join(''):`<tr><td colspan="${cols.length}" class="empty">No matching rows${state.view==='credits'?' — enrich metadata or loosen filters':''}</td></tr>`;els.mobileList.innerHTML=pageRows.length?pageRows.map(mobileCard).join(''):'<div class="empty">No matching rows</div>';els.pageInfo.textContent=total?`${full(start+1)}–${full(Math.min(start+state.pageSize,total))} of ${full(total)} • Page ${state.page}/${pages}`:'0 results';els.prevBtn.disabled=state.page<=1;els.nextBtn.disabled=state.page>=pages;bindGameClicks();bindCreditClicks();renderChart()}
function renderMatrix''', 'render')

